using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CoastalTallPNGPines {
const string D="Assets/Scenes/Oasis/CoastalTerrain";static CoastalTallPNGPines(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoastalTallPNGPines.request"))return;try{File.Delete("CoastalTallPNGPines.request");}catch(IOException){return;}Run();}
static void Run(){try{var seen=new HashSet<Mesh>();int pinned=0;foreach(string guid in AssetDatabase.FindAssets("t:Prefab",new[]{D+"/Prefabs"})){string path=AssetDatabase.GUIDToAssetPath(guid);if(!Path.GetFileName(path).StartsWith("Pine_")&&!Path.GetFileName(path).StartsWith("Natural Pine"))continue;var prefab=PrefabUtility.LoadPrefabContents(path);foreach(var filter in prefab.GetComponentsInChildren<MeshFilter>()){var mesh=filter.sharedMesh;if(!seen.Add(mesh)||mesh.name.Contains("Tall detailed v4"))continue;var p=mesh.vertices;var w=new List<Vector4>();mesh.GetUVs(1,w);var groups=new Dictionary<Vector2,List<int>>();for(int i=0;i<p.Length;i++){var key=new Vector2(w[i].y,w[i].z);if(!groups.ContainsKey(key))groups[key]=new List<int>();groups[key].Add(i);}foreach(var group in groups){float bottom=group.Value.Min(i=>p[i].y);foreach(int i in group.Value){p[i].y=bottom+(p[i].y-bottom)*1.22f;if(w[i].x<.00001f)pinned++;}}mesh.vertices=p;mesh.RecalculateBounds();var bounds=mesh.bounds;bounds.Expand(1);mesh.bounds=bounds;mesh.name="Tall detailed v4 3D PNG pine";EditorUtility.SetDirty(mesh);}prefab.GetComponent<LODGroup>().RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,path);PrefabUtility.UnloadPrefabContents(prefab);}
var importer=(TextureImporter)AssetImporter.GetAtPath(D+"/Details/Pine Needle Branch Cutout.png");importer.filterMode=FilterMode.Trilinear;importer.anisoLevel=8;importer.mipMapsPreserveCoverage=true;importer.alphaTestReferenceValue=.24f;importer.SaveAndReimport();var mat=AssetDatabase.LoadAssetAtPath<Material>(D+"/Details/Shared 3D Forest Pine.mat");mat.SetFloat("_Cutoff",.24f);mat.SetFloat("_WindStrength",.30f);mat.SetFloat("_WindSpeed",1.05f);mat.SetColor("_Tint",new Color(.95f,1,.94f));mat.SetFloat("_PreviewTime",-1);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);mat.SetFloat("_PreviewTime",0);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Tall-Detailed-PNG-Pines-A"});mat.SetFloat("_PreviewTime",2);capture.Invoke(null,new object[]{scene,new Vector3(813,31,150),new Vector3(819,35,350),"Tall-Detailed-PNG-Pines-B"});mat.SetFloat("_PreviewTime",-1);EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/TallPNGPineReport.txt","SUCCESS meshes="+seen.Count+" anchored base vertices="+pinned+"; tree heights +22%; fine needles preserved with alpha cutoff .24 and coverage mipmaps; wind .30m, speed1.05; same wind in forward/depth/normals/shadow passes; live wind restored; no added geometry; shader errors="+ShaderUtil.GetShaderMessages(mat.shader).Count(m=>m.severity.ToString()=="Error"));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/TallPNGPineReport.txt","FAILED "+e);Debug.LogException(e);}}
}
